import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.BPmc_f4o.js";const m=JSON.parse('{"title":"Tecs CLI","description":"The planned tecs command line tool: its commands, what a project is, and what it will not do","frontmatter":{"description":"The planned tecs command line tool: its commands, what a project is, and what it will not do","outline":"deep"},"headers":[],"relativePath":"cli/index.md","filePath":"cli/index.md"}'),n={name:"cli/index.md"};function c(r,t,s,i,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /cli.md for this page in Markdown format</div><h1 id="tecs-cli" tabindex="-1">Tecs CLI <a class="header-anchor" href="#tecs-cli" aria-label="Permalink to &quot;Tecs CLI&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Not built yet</p><p>The <code>tecs</code> command does not exist on this branch. This page records the shape it is planned to take so that nothing else in the site has to pretend it is already there. Everything below is a plan, not a reference, and the commands cannot be run today.</p><p>Build and run through <code>make</code> in the meantime. See <a href="/getting-started.html">getting started</a>.</p></div><p>The command line tool is meant to be the primary way to use Tecs: install one file, run <code>tecs new</code>, and never see CMake, Make, LuaRocks or a C compiler. It links nothing on a user&#39;s machine and needs no toolchain there.</p><h2 id="the-planned-commands" tabindex="-1">The planned commands <a class="header-anchor" href="#the-planned-commands" aria-label="Permalink to &quot;The planned commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>tecs new</code></td><td>Scaffold a working project from a template carried inside the binary</td></tr><tr><td><code>tecs build</code></td><td>Compile the project&#39;s Teal, copy assets, build a shader pack</td></tr><tr><td><code>tecs run</code></td><td>Build, then run the project&#39;s entry through the host</td></tr><tr><td><code>tecs check</code></td><td>Type-check the project against the installed Teal tree</td></tr><tr><td><code>tecs test</code></td><td>Compile and run the project&#39;s specs</td></tr><tr><td><code>tecs dist</code></td><td>Package the game for players, for the host platform only</td></tr><tr><td><code>tecs mcp</code></td><td>Serve the debug server to agent clients over stdio</td></tr><tr><td><code>tecs call</code></td><td>Call a tool on a running game</td></tr><tr><td><code>tecs info</code></td><td>Versions, project status, next step, and third-party licence notices</td></tr><tr><td><code>tecs clean</code></td><td>Remove build output</td></tr><tr><td><code>tecs completions</code></td><td>Print a bash, zsh or fish completion script</td></tr><tr><td><code>tecs help</code></td><td>Command overview, plus <code>--version</code> and <code>--quiet</code> as global flags</td></tr></tbody></table><p>An <code>api</code> command that looks up framework and project symbols is planned for a later phase.</p>',7)])])}const u=e(n,[["render",c]]);export{m as __pageData,u as default};
